15: /**
16:  * Ties the JobRunr {@link BackgroundJobServer} to the lifecycle of the application context that
17:  * created it, so jobs are only processed while that context is fully refreshed and not yet closing.
18:  * <p>
19:  * While OpenMRS starts up, the application context is refreshed before modules are started, and
20:  * again once they are, so a job processed at the end of the first refresh fails on a module's task
21:  * class that is not loaded yet. Startup code that refreshes contexts before starting modules calls
22:  * {@link #deferStartUntilOpenmrsStarted()} first, and the server then starts only once
23:  * {@link #openmrsStarted()} reports that OpenMRS has finished starting.
24:  *
25:  * @since 2.9.0
26:  */
27: public class JobRunrServerLifecycle implements SmartLifecycle {
28: 
29: 	private static volatile boolean startDeferred = false;
30: 
31: 	private final BackgroundJobServer backgroundJobServer;
32: 
33: 	private volatile boolean running;
34: 
35: 	public JobRunrServerLifecycle(BackgroundJobServer backgroundJobServer) {
36: 		this.backgroundJobServer = backgroundJobServer;
37: 	}
38: 
39: 	/**
40: 	 * Keeps background job servers from starting with their application context until
41: 	 * {@link #openmrsStarted()} is called.
42: 	 */
43: 	public static void deferStartUntilOpenmrsStarted() {
44: 		startDeferred = true;
45: 	}
46: 
47: 	/**
48: 	 * Starts the background job server if its start was deferred until OpenMRS has started.
49: 	 */
50: 	public synchronized void openmrsStarted() {
51: 		startDeferred = false;
52: 		if (!running) {
53: 			start();
54: 		}
55: 	}
56: 
57: 	@Override
58: 	public synchronized void start() {
59: 		if (startDeferred) {
60: 			return;
61: 		}
62: 		backgroundJobServer.start();
63: 		running = true;
64: 	}
65: 
66: 	@Override
67: 	public synchronized void stop() {
68: 		running = false;
69: 		backgroundJobServer.stop();
70: 	}
71: 
72: 	@Override
73: 	public boolean isRunning() {
74: 		return running;
75: 	}
76: }
